const line = (r, i) => { const f = r.fields; const d = f.started_at ? DateTime.fromISO(f.started_at).setZone('Europe/Rome').toFormat('d LLL HH:mm') : '';
  return (i + 1) + '. ' + d + ' · ' + String(f.keywords || '').split('\n').join(', ') + ' · ' + (f.mode === 'today' ? '24 h' : '7 days'); };
const recs = $json.records || [];
const text = recs.length ? '## Reports of the last 14 days\n' + recs.map(line).join('\n') + '\n\nReply with a number for its summary.'
  : 'No delivered reports in the last 14 days. Start one with search <topic>.';
return [{ json: { chat_id: $('Store Settings').first().json.chat_id, text } }];

const c = $('Store Settings').first().json;
const recs = $json.records || [];
const idx = c.command === 'number' ? c.number - 1 : 0;
const r = recs[idx];
return [{ json: r ? { found: true, record_id: r.id, run: r.fields } : { found: false,
  message: recs.length ? 'There is no report number ' + c.number + '. Send list to see the numbers.' : 'No delivered reports in the last 14 days. Start one with search <topic>.' } }];

const run = $('Pick Report').first().json.run;
const md = String(run.briefing || '');
const inShort = (md.split(/^## /m).find(s => s.startsWith('In short')) || '').replace(/^In short\s*/, '').trim();
const topics = (md.match(/^## (.+)$/gm) || []).map(h => h.slice(3)).filter(t => t !== 'In short' && t !== 'Sources');
const counts = {};
for (const r of ($json.records || [])) { const l = r.fields.label || 'Not checked'; counts[l] = (counts[l] || 0) + 1; }
const text = ['## ' + String(run.keywords || '').split('\n').join(', ') + ' (' + (run.mode === 'today' ? 'last 24 hours' : 'last 7 days') + ')',
  inShort || 'This report has no briefing text.', '',
  topics.length ? '## Topics\n' + topics.map(t => '- ' + t).join('\n') : '',
  Object.keys(counts).length ? '## Claims checked\n' + Object.entries(counts).map(([l, n]) => '[' + l + '] ' + n).join('\n') : '',
  run.pdf_link ? '\nPDF: ' + run.pdf_link : '', '\nSend provide-all for the full briefing.'].filter(Boolean).join('\n');
return [{ json: { chat_id: $('Store Settings').first().json.chat_id, text } }];

const r = ($json.records || [])[0];
const text = r ? '## ' + String(r.fields.keywords || '').split('
').join(', ') + '
' + (r.fields.briefing || 'This report has no briefing text.') + (r.fields.pdf_link ? '

PDF: ' + r.fields.pdf_link : '')
  : 'No delivered report yet. Start one with search <topic>.';
return [{ json: { chat_id: $('Store Settings').first().json.chat_id, text } }];

// The stories of the asked period, newest first: by day up to 14 days, by week for longer periods.
const rc = $('Store Settings').first().json;
const rows = $input.all().map(i => i.json).filter(r => r && r.story_number);
let text;
if (rc.range_error) text = rc.range_error;
else if (!rows.length) text = '## Stories from ' + rc.range_label + '\nNo stories were checked in this period.';
else {
  const days = (new Date(rc.to) - new Date(rc.from)) / 864e5 + 1;
  const name = (d) => new Date(d + 'T12:00:00Z').toLocaleDateString('en-GB', { weekday: 'short', day: 'numeric', month: 'short', timeZone: 'UTC' });
  const weekOf = (d) => { const x = new Date(d + 'T12:00:00Z'); x.setUTCDate(x.getUTCDate() - (x.getUTCDay() + 6) % 7); return 'Week of ' + x.toLocaleDateString('en-GB', { day: 'numeric', month: 'short', timeZone: 'UTC' }); };
  const groups = new Map();
  for (const r of rows) { const k = days <= 14 ? name(r.found_on) : weekOf(r.found_on); if (!groups.has(k)) groups.set(k, []); groups.get(k).push(r); }
  const lines = ['## Stories from ' + rc.range_label, rows.length + (rows.length === 1 ? ' story' : ' stories') + (days > 14 ? ', titles only' : '')];
  for (const [k, list] of groups) { lines.push('', '### ' + k); for (const r of list) lines.push('[' + r.label + '] #' + r.story_number + ' ' + r.title); }
  lines.push('', 'Send dig and a number for the full story.');
  text = lines.join('\n');
}
return [{ json: { chat_id: rc.chat_id, text } }];

// One story in full (explainer, sources, every update), or a short choice when several stories match.
const rc = $('Store Settings').first().json;
const rows = $input.all().map(i => i.json).filter(r => r && r.story_number);
const STATUS = { confirmed: 'Confirmed', stated_only: 'Stated by the source only', not_disclosed: 'Not disclosed', contradicted: 'Contradicted' };
const date = (d) => new Date(String(d).slice(0, 10) + 'T12:00:00Z').toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric', timeZone: 'UTC' });
// Every link with its publication date; pages older than the run's recent window are marked background.
const day = (d) => d ? date(d) : 'date unknown';
let pages = {};
const dated = (u) => { const e = pages[u] || {}; return day(e.published) + (e.when === 'background' ? ', background' : ''); };
const links = (label, t) => String(t || '').split('\n').filter(Boolean).map(u => '- ' + label + ', ' + dated(u) + ': ' + u);
// Who wrote a post, from its address: @name on X, r/name on Reddit, or Hacker News.
const whoOf = (u) => { let m = String(u).match(/(?:x|twitter)\.com\/([^\/?#]+)\/status/i); if (m) return '@' + m[1] + ' on X'; m = String(u).match(/reddit\.com\/r\/([^\/?#]+)/i); if (m) return 'r/' + m[1] + ' on Reddit'; return /ycombinator/.test(String(u)) ? 'Hacker News' : 'Post'; };
let text, follow = {};
const cmd = rc.command === 'update' ? 'update' : 'dig';
if (!rows.length) text = rc.dig_number ? 'There is no story #' + rc.dig_number + '. Send list to see the numbers.' : 'No story matches "' + rc.topic + '". Try other words, or list to browse by date.';
// Words: the best match is shown at once when it ranks at least twice as high as the next one.
else if (!rc.dig_number && rows.length > 1 && !(Number(rows[0].rank) >= 2 * Number(rows[1].rank))) text = ['## Several stories match', ...rows.map(r => '[' + r.label + '] #' + r.story_number + ' ' + r.title + ' (' + date(r.found_on) + ')'), '', 'Send ' + cmd + ' and the number of the one you mean.'].join('\n');
else if (rc.command === 'update') {
  // One clear story: the bot answers at once and Follow Up Story sends the update when it is done.
  const r = rows[0]; const ups = r.updates || [];
  text = 'Looking for news on #' + r.story_number + ' · ' + r.title + ' published since ' + date(ups.length ? ups[ups.length - 1].asked_on : r.found_on) + '. I will send what I find here in about a minute.';
  follow = { function: 'open', follow_up: true, story_number: r.story_number, question: rc.question || '' };
}
else {
  const r = rows[0]; const x = r.explainer;
  try { pages = Object.fromEntries(JSON.parse(r.evidence || '[]').map(e => [e.url, e])); } catch (e) { pages = {}; }
  const l = ['## #' + r.story_number + ' · ' + r.title, '[' + r.label + '] found on ' + date(r.found_on) + (r.mode === 'today' ? ' (daily run)' : ' (weekly run)')];
  // The original posts come first, oldest first.
  const posts = [...(r.posts || [])].sort((a, b) => String(a.published_at || '').localeCompare(String(b.published_at || '')));
  if (posts.length) l.push('', '### Where it came from', ...posts.map(p => '- ' + whoOf(p.url) + ', ' + day(p.published_at) + ': ' + p.url + (p.linked_url ? '\n  linking to ' + p.linked_url : '')));
  if (x) {
    l.push('', '### What happened', x.what_happened);
    if ((x.status_points || []).length) l.push('', '### Confirmed and not confirmed', ...x.status_points.map(p => '- ' + (STATUS[p.status] || p.status) + ': ' + p.point + (p.source ? ' (' + dated(p.source) + ') ' + p.source : '')));
    if (r.label === 'Disputed' && x.two_sides && (x.two_sides.side_a || x.two_sides.side_b)) l.push('', '### Both sides', '- One side: ' + x.two_sides.side_a, '- Other side: ' + x.two_sides.side_b);
    l.push('', '### Why it matters', x.why_it_matters, '', '### Open question', x.open_question);
  } else l.push('', r.gist || r.claim || '');
  const src = [...links('Official', r.official_links), ...links('Supporting', r.supporting_links), ...links('Contradicting', r.contradicting_links)];
  if (src.length) l.push('', '### Sources', ...src);
  if (r.pdf_link) l.push('', 'PDF of the report: ' + r.pdf_link);
  const ups = r.updates || [];
  l.push('', '### Updates');
  if (!ups.length) l.push('No update asked yet. Send update ' + r.story_number + ' to look for news since ' + date(r.found_on) + '.');
  for (const u of ups) { l.push('', '### ' + date(u.asked_on) + (u.question ? ' (you asked: ' + u.question + ')' : ''), u.result, ...String(u.links || '').split('\n').filter(Boolean).map(x => '- ' + x)); }
  const convs = r.conversations || [];
  if (convs.length) { l.push('', '### Your saved conversations'); for (const c of convs) l.push('- ' + date(c.saved_on) + ': ' + String(c.summary || '').split('\n')[0]); }
  l.push('', 'Ask me anything about this story here. Send save or close to keep the conversation, forget to drop it.');
  text = l.join('\n');
  follow = { function: 'open', follow_up: false, story_number: r.story_number, question: '' };
}
return [{ json: { chat_id: rc.chat_id, message_id: rc.message_id, text, ...follow } }];
